def _parse(version):
    # Build metadata is ignored entirely.
    version = version.split('+', 1)[0]
    if '-' in version:
        core, pre = version.split('-', 1)
        pre_ids = pre.split('.')
    else:
        core = version
        pre_ids = None
    nums = tuple(int(part) for part in core.split('.'))
    return nums, pre_ids


def _cmp_identifier(x, y):
    x_num = x.isdigit()
    y_num = y.isdigit()
    if x_num and y_num:
        xi, yi = int(x), int(y)
        return (xi > yi) - (xi < yi)
    if x_num:
        return -1  # numeric has lower precedence than non-numeric
    if y_num:
        return 1
    return (x > y) - (x < y)


def _cmp_prerelease(a_ids, b_ids):
    # None means no pre-release, which has higher precedence.
    if a_ids is None and b_ids is None:
        return 0
    if a_ids is None:
        return 1
    if b_ids is None:
        return -1
    for x, y in zip(a_ids, b_ids):
        c = _cmp_identifier(x, y)
        if c != 0:
            return c
    return (len(a_ids) > len(b_ids)) - (len(a_ids) < len(b_ids))


def compare_versions(a: str, b: str) -> int:
    a_nums, a_pre = _parse(a)
    b_nums, b_pre = _parse(b)
    if a_nums != b_nums:
        return 1 if a_nums > b_nums else -1
    return _cmp_prerelease(a_pre, b_pre)
